package run.ikaros.finance; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/transactions/{transactionId}/actions") public class VoidTransactionController{private final VoidTransactionService service;public VoidTransactionController(VoidTransactionService s){service=s;}@PostMapping("/void")public Mono<TransactionView> voidTransaction(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID transactionId){return service.voidTransaction(a,transactionId);}}
